import pathlib,re,subprocess
p=re.compile(r'(?i)(aws_access_key_id|aws_secret_access_key|aws_session_token|github_token|hf_token|huggingface_token|api_key|apikey|gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}|hf_[A-Za-z0-9]{20,}|AKIA[A-Z0-9]{16}|ASIA[A-Z0-9]{16}|BEGIN .*PRIVATE KEY)')
for f in subprocess.check_output(['git','ls-files','-z']).decode().split('\\0'):
 if not f:continue
 try:s=pathlib.Path(f).read_text()
 except:continue
 for n,l in enumerate(s.splitlines(),1):
  matches=p.findall(l)
  if matches:print(f,n,','.join(m if len(m)<25 else 'token-pattern' for m in matches))
print('commits',subprocess.check_output(['git','rev-list','--all','--count']).decode().strip())
