/bin/bash -lc "cat > /tmp/dclm-sanitize.py <<'PY'
import pathlib,re,subprocess,json,hashlib
root=pathlib.Path('/app/dclm')
files=[root/f for f in subprocess.check_output(['git','ls-files','-z'],cwd=root).decode().split('\\0') if f]
patterns={
'<your-aws-access-key-id>':r'(?<"'![A-Za-z0-9])(?:AKIA|ASIA)[A-Z0-9]{16}(?![A-Za-z0-9])'"',
'<your-github-token>':r'\\b(?:gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,})\\b',
'<your-huggingface-token>':r'\\bhf_[A-Za-z0-9]{20,}\\b',
}
replacements={}
for p in files:
 try:s=p.read_text()
 except (UnicodeError,OSError):continue
 for placeholder,pattern in patterns.items():
  for m in re.finditer(pattern,s):replacements[m[0]]=placeholder
 if p.name in ['process.py','ray_cluster.yaml']:
  for m in re.finditer(r'AWS_SECRET_ACCESS_KEY[\\\"\\x27\\]]*\\s*=\\s*[\\\"\\x27]?([A-Za-z0-9/+=]{30,})',s):replacements[m[1]]='<your-aws-secret-access-key>'
before={str(p.relative_to(root)):hashlib.sha256(p.read_bytes()).hexdigest() for p in files if p.is_file()}
changed=[]
for p in files:
 if not p.is_file():continue
 old=p.read_bytes();new=old
 for secret,placeholder in replacements.items():new=new.replace(secret.encode(),placeholder.encode())
 if new"'!=old:p.write_bytes(new);changed.append(str(p.relative_to(root)))
assert len(replacements)>=4
for p in files:
 if p.is_file():assert all(v.encode() not in p.read_bytes() for v in replacements)
assert all(hashlib.sha256((root/f).read_bytes()).hexdigest()==h for f,h in before.items() if f not in changed)
pathlib.Path('"'/tmp/dclm-secret-replacements.json').write_text(json.dumps(replacements));pathlib.Path('/tmp/dclm-secret-replacements.json').chmod(0o600)
print('Distinct credentials replaced:',len(replacements))
print('Changed files:',*changed,sep='\\n')
print('Verified original values absent and other tracked files byte-for-byte unchanged.')
PY
python /tmp/dclm-sanitize.py
/tmp/dclm-gitleaks dir . --redact --report-format json --report-path /tmp/dclm-after.json --no-banner --log-level error"

